    { V ut2_ = py::as_seq(m_triggered(Args{SV("plant:土豆地雷"), V(700.0)})); L_z = ut2_.idx(0); L_before = ut2_.idx(1); } 
    (void)(m_assertNotIn(Args{SV("灰烬"), L_z}));
