V C_DeathmatchTests::m_test_sturdy_grave_and_torch_are_not_banned(const Args& A) {
    V L_b;
    V L_error;
    (void)(m_assertFalse(Args{pm_balance::f_deathmatch_blocked(Args{rd(pm_catalog::CARDS, pm_test_pvp_65_features::STURDY)})}));
    (void)(m_assertFalse(Args{pm_balance::f_deathmatch_blocked(Args{rd(pm_catalog::CARDS, pm_test_pvp_65_features::TORCH)})}));
    (void)(m_assertTrue(Args{pm_balance::f_deathmatch_blocked(Args{rd(pm_catalog::CARDS, SV("zombie:脑光墓碑"))})}));
    (void)(m_assertTrue(Args{pm_balance::f_deathmatch_blocked(Args{rd(pm_catalog::CARDS, SV("plant:向日葵"))})}));
    L_b = m_battle(Args({}, {{SY("zombies"), V::list({SV("zombie:脑光墓碑"), pm_test_pvp_65_features::STURDY, pm_test_pvp_65_features::TORCH, SV("zombie:普通僵尸")})}}));
    (void)(m_park_heroes(Args{L_b}));
    pvz::setattr(L_b, SY("deathmatch"), V(true));
    (void)(m_assertIsNotNone(Args{m_deploy(Args{L_b, SV("zombie"), pm_test_pvp_65_features::STURDY, V(24.0)})}));
    (void)(m_assertIsNotNone(Args{m_deploy(Args{L_b, SV("zombie"), pm_test_pvp_65_features::TORCH, V(20.0)})}));
    L_error = m_cmd(Args({L_b, SV("zombie"), SV("deploy")}, {{SY("card"), SV("zombie:脑光墓碑")}, {SY("x"), (V(26.5) * pvz::getattr(L_b, SY("tile")))}, {SY("y"), (V(9.5) * pvz::getattr(L_b, SY("tile")))}}));
    (void)(m_assertIn(Args{SV("死斗"), L_error}));
    (void)(m_assertIn(Args{SV("死斗期间仍可放置"), pm_catalog::f_describe(Args{pm_test_pvp_65_features::STURDY})}));
    return V::none();
}

